.btn-primary {
  background: var(--color-primary);
  color: var(--color-surface);
  border: 0;
  border-radius: var(--radius-lg);
  cursor: pointer;
}

.btn-primary:hover {
  background: var(--color-primary-dark);
}

.btn-primary:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus);
}
